1	import { apiClient } from "./client";
2	import type { Issue, IssueDetail, IssueFilters, CreateIssueData, UpdateIssueData, HistoryEvent } from "@/types";
3	
4	/**
5	 * Build query string from filters.
6	 */
7	function buildQueryString(filters: IssueFilters): string {
8	  const params = new URLSearchParams();
9	  if (filters.status) params.set("status", filters.status);
10	  if (filters.assignee) params.set("assignee", filters.assignee);
11	  if (filters.tags && filters.tags.length > 0) params.set("tags", filters.tags.join(","));
12	  if (filters.parentId !== undefined) params.set("parentId", filters.parentId === null ? "null" : filters.parentId);
13	  if (filters.search) params.set("search", filters.search);
14	  const qs = params.toString();
15	  return qs ? `?${qs}` : "";
16	}
17	
18	export const issuesApi = {
19	  list(filters: IssueFilters = {}): Promise<Issue[]> {
20	    return apiClient<Issue[]>(`/issues${buildQueryString(filters)}`);
21	  },
22	
23	  create(data: CreateIssueData): Promise<{ id: string }> {
24	    return apiClient<{ id: string }>("/issues", {
25	      method: "POST",
26	      body: JSON.stringify(data),
27	    });
28	  },
29	
30	  view(id: string): Promise<IssueDetail> {
31	    return apiClient<IssueDetail>(`/issues/${id}`);
32	  },
33	
34	  update(id: string, data: UpdateIssueData): Promise<{ result: string }> {
35	    return apiClient<{ result: string }>(`/issues/${id}`, {
36	      method: "PATCH",
37	      body: JSON.stringify(data),
38	    });
39	  },
40	
41	  history(id: string): Promise<HistoryEvent[]> {
42	    return apiClient<HistoryEvent[]>(`/issues/${id}/history`);
43	  },
44	
45	  next(assignee: string): Promise<IssueDetail | { result: string; message: string }> {
